export type ApiProblemFieldErrors = { [key: string]: string[] };

export interface ApiProblem {
  type: string;
  title: string;
  status: number;
  code: string;
  detail?: string;
  fieldErrors?: ApiProblemFieldErrors;
  traceId?: string;
}

/**
 * Request validation failed
 */
export type ValidationProblemResponse = ApiProblem;

/**
 * Domain or idempotency conflict
 */
export type ConflictProblemResponse = ApiProblem;

/**
 * Quote expired
 */
export type ExpiredProblemResponse = ApiProblem;

/**
 * Resource not found
 */
export type NotFoundProblemResponse = ApiProblem;

/**
 * Demo backend or database is unavailable
 */
export type UnavailableResponse = ApiProblem;

/**
 * Customer bearer or workforce authentication is required or invalid
 */
export type UnauthorizedProblemResponse = ApiProblem;

/**
 * The authenticated customer identity is unbound, restricted, or not activated through onboarding, or the workforce role lacks permission
 */
export type ForbiddenProblemResponse = ApiProblem;

